package br.com.orientec.backend.adapter.out.persistence.entity.os; import jakarta.persistence.*; @Entity @Table(name="os_status") public class OsStatus { @Id private Short id; @Column(nullable=false,unique=true) private String codigo; @Column(nullable=false) private String descricao; @Column(nullable=false) private boolean ativo=true; public OsStatus(){} public Short getId(){return id;} public String getCodigo(){return codigo;} public String getDescricao(){return descricao;} public boolean isAtivo(){return ativo;} public void setId(Short v){id=v;} public void setCodigo(String v){codigo=v;} public void setDescricao(String v){descricao=v;} public void setAtivo(boolean v){ativo=v;} }